-- PT105-S2-Q7. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT105-S2-Q7$batch11$ AND q.stimulus=$batch11$The crux of creativity resides in the ability to manufacture variation on a theme. If we look at the history of science, for instance, we see that every idea is built upon a thousand related ideas. Careful analysis leads us to understand that what we choose to call a new theme or a new discovery is itself always and without exception some sort of variation, on a deep level, of previous themes.$batch11$ AND q.prompt=$batch11$If all of the statements in the passage are true, each of the following must also be true EXCEPT:$batch11$ AND q.correct_choice=$batch11$E$batch11$) THEN RAISE EXCEPTION 'Question changed: PT105-S2-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT105-S2-Q7$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S2-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT105-S2-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Creativity is, at its core, the ability to make variations on a theme. Every scientific idea is built on many related ideas. Every new theme or discovery is always, without exception, a variation on earlier themes.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$This is an EXCEPT question, so four answers follow from the passage and one does not. Look for the answer that breaks "always and without exception." Any answer saying some discovery is not a variation contradicts the passage.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Find the answer that says some discovery is not a variation on earlier themes.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT105-S2-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$If creativity is the ability to make variations, lacking that ability means lacking creativity.$batch11$), ($batch11$B$batch11$, $batch11$Every idea is built on a thousand related ideas, so none is fully independent.$batch11$), ($batch11$C$batch11$, $batch11$Careful analysis shows every discovery is a variation of earlier themes, so analysis can reveal those themes.$batch11$), ($batch11$D$batch11$, $batch11$Every discovery is a variation on a theme. Anyone who made a great discovery made such a variation.$batch11$), ($batch11$E$batch11$, $batch11$The passage says every discovery is a variation, "always and without exception." This says some are not. It contradicts the passage.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT105-S2-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
